interface Caixa<T> {
  etiqueta: string;
  conteudo: T;
}

const manual: Caixa<string> = { etiqueta: "docs", conteudo: "manual.pdf" };
const medidas: Caixa<number[]> = { etiqueta: "sensor", conteudo: [12, 15, 11] };

function desembrulhar<T>(caixa: Caixa<T>): T {
  return caixa.conteudo;
}

const texto = desembrulhar(manual); // string
const numeros = desembrulhar(medidas); // number[]

console.log(texto.toUpperCase()); // "MANUAL.PDF"
console.log(numeros.length); // 3

// @ts-expect-error Caixa<string> exige conteudo string; 42 é number
const errada: Caixa<string> = { etiqueta: "erro", conteudo: 42 };

// @ts-expect-error nao existe uma Caixa "sem T": o argumento de tipo é obrigatório no uso
const semArgumento: Caixa = { etiqueta: "x", conteudo: "y" };

type Resultado<T> =
  | { ok: true; valor: T }
  | { ok: false; erro: string };

function dividir(a: number, b: number): Resultado<number> {
  if (b === 0) {
    return { ok: false, erro: "divisão por zero" };
  }
  return { ok: true, valor: a / b };
}

function lerConfig(chave: string): Resultado<string> {
  const tabela: Record<string, string | undefined> = { porta: "8080" };
  const valor = tabela[chave];
  if (valor === undefined) {
    return { ok: false, erro: "chave ausente: " + chave };
  }
  return { ok: true, valor };
}

function descrever<T>(r: Resultado<T>): string {
  return r.ok ? "ok: " + String(r.valor) : "erro: " + r.erro;
}

console.log(descrever(dividir(10, 4))); // "ok: 2.5"
console.log(descrever(dividir(1, 0))); // "erro: divisão por zero"

const config = lerConfig("host");
if (config.ok) {
  console.log(config.valor.toUpperCase());
} else {
  console.log(config.erro); // "chave ausente: host"
}

interface Repositorio<T, ID> {
  guardar(item: T): void;
  procurar(id: ID): T | undefined;
  todos(): readonly T[];
}

interface Utilizador {
  id: number;
  nome: string;
}

function criarRepositorio<T, ID>(chave: (item: T) => ID): Repositorio<T, ID> {
  const itens: T[] = [];
  return {
    guardar(item) {
      itens.push(item);
    },
    procurar(id) {
      return itens.find((item) => chave(item) === id);
    },
    todos() {
      return itens;
    },
  };
}

const utilizadores = criarRepositorio<Utilizador, number>((u) => u.id);
utilizadores.guardar({ id: 1, nome: "Ana" });
utilizadores.guardar({ id: 2, nome: "Bruno" });

console.log(utilizadores.procurar(2)?.nome); // "Bruno"
console.log(utilizadores.todos().length); // 2

// @ts-expect-error o ID deste repositório é number, não string
utilizadores.procurar("2");

class Pilha<T> {
  itens: T[];

  constructor(iniciais: T[] = []) {
    this.itens = [...iniciais];
  }

  empilhar(item: T): void {
    this.itens.push(item);
  }

  desempilhar(): T | undefined {
    return this.itens.pop();
  }

  espreitar(): T | undefined {
    return this.itens[this.itens.length - 1];
  }

  tamanho(): number {
    return this.itens.length;
  }
}

const pendentes = new Pilha<string>();
pendentes.empilhar("rever PR");
pendentes.empilhar("escrever testes");

console.log(pendentes.espreitar()?.toUpperCase()); // "ESCREVER TESTES"
console.log(pendentes.desempilhar()); // "escrever testes"
console.log(pendentes.tamanho()); // 1

// @ts-expect-error a pilha é de string: um number não entra
pendentes.empilhar(7);

const historico = new Pilha([3, 1, 4]); // Pilha<number>, inferida pelo construtor
console.log(historico.desempilhar()! + 1); // 5

const solta = new Pilha(); // Pilha<unknown>: nada por onde inferir
solta.empilhar("texto");
solta.empilhar(42);
console.log(solta.tamanho()); // 2

class Registo {
  linhas: string[] = [];

  anotar<T>(etiqueta: string, valor: T): T {
    this.linhas.push(etiqueta + "=" + String(valor));
    return valor;
  }
}

const registo = new Registo();
const porta = registo.anotar("porta", 8080); // number
const ambiente = registo.anotar("ambiente", "producao"); // string

console.log(porta + 1); // 8081
console.log(ambiente.toUpperCase()); // "PRODUCAO"
console.log(registo.linhas.join(" | ")); // "porta=8080 | ambiente=producao"

class Caixa<T> {
  conteudo: T;

  constructor(conteudo: T) {
    this.conteudo = conteudo;
  }

  mapear<U>(transformar: (valor: T) => U): Caixa<U> {
    return new Caixa(transformar(this.conteudo));
  }
}

const numero = new Caixa(42); // Caixa<number>: T fica fixo na instância
const emTexto = numero.mapear((n) => "n" + n); // Caixa<string>: U vem desta chamada
const grande = numero.mapear((n) => n > 10); // Caixa<boolean>: U vem daquela chamada

console.log(emTexto.conteudo); // "n42"
console.log(grande.conteudo); // true

class Caixa<T> {
  conteudo: T;

  constructor(conteudo: T) {
    this.conteudo = conteudo;
  }

  // @ts-expect-error um campo estático não pode usar o T da classe: T só existe por instância
  static predefinido: T | undefined = undefined;

  // @ts-expect-error o mesmo vale para métodos estáticos
  static criar(valor: T): Caixa<T> {
    return new Caixa(valor);
  }

  // a alternativa: o próprio método estático declara o seu parâmetro de tipo
  static criarSeguro<U>(valor: U): Caixa<U> {
    return new Caixa(valor);
  }
}

const quarenta = Caixa.criarSeguro(40); // Caixa<number>
const saudacao = Caixa.criarSeguro("olá"); // Caixa<string>

console.log(quarenta.conteudo + 2); // 42
console.log(saudacao.conteudo.length); // 3

type ComparadorGenerico = <T>(a: T, b: T) => number;
type ComparadorDe<T> = (a: T, b: T) => number;

// a função é que é genérica: tem de servir para qualquer T, logo nada pode assumir sobre a e b
const porIgualdade: ComparadorGenerico = (a, b) => (a === b ? 0 : 1);

// o tipo é que é parametrizado: cada uso fixa o T e o corpo já sabe com que trabalha
const porValor: ComparadorDe<number> = (a, b) => a - b;
const porComprimento: ComparadorDe<string> = (a, b) => a.length - b.length;

console.log(porIgualdade(1, 1)); // 0
console.log(porValor(3, 10)); // -7
console.log(porComprimento("abc", "z")); // 2

// @ts-expect-error num ComparadorGenerico a e b podem ser de qualquer tipo: subtrair não compila
const invalido: ComparadorGenerico = (a, b) => a - b;

function ordenar<T>(itens: readonly T[], comparar: ComparadorDe<T>): T[] {
  return [...itens].sort(comparar);
}

console.log(ordenar([3, 1, 2], porValor).join(",")); // "1,2,3"
console.log(ordenar(["abc", "z", "de"], porComprimento).join(",")); // "z,de,abc"

