interface Par<A, B> {
  primeiro: A;
  segundo: B;
}

function trocar<A, B>(par: Par<A, B>): Par<B, A> {
  return { primeiro: par.segundo, segundo: par.primeiro };
}

const original: Par<string, number> = { primeiro: "idade", segundo: 41 };
const trocado = trocar(original); // Par<number, string>

console.log(trocado.primeiro + 1); // 42
console.log(trocado.segundo.toUpperCase()); // "IDADE"

// @ts-expect-error depois de trocar, primeiro é number: já não é uma string
const rotulo: string = trocado.primeiro;

type Opcao<T> =
  | { presente: true; valor: T }
  | { presente: false };

function algum<T>(valor: T): Opcao<T> {
  return { presente: true, valor };
}

function valorOu<T>(opcao: Opcao<T>, alternativa: T): T {
  return opcao.presente ? opcao.valor : alternativa;
}

function primeiroPar(numeros: readonly number[]): Opcao<number> {
  const encontrado = numeros.find((n) => n % 2 === 0);
  if (encontrado === undefined) {
    return { presente: false };
  }
  return { presente: true, valor: encontrado };
}

console.log(valorOu(primeiroPar([1, 3, 6, 8]), -1)); // 6
console.log(valorOu(primeiroPar([1, 3, 5]), -1)); // -1
console.log(valorOu(algum("texto"), "vazio")); // "texto"

const nada: Opcao<string> = { presente: false };
// @ts-expect-error valor só existe no membro em que presente é true
const perdido = nada.valor;

class Fila<T> {
  itens: T[];

  constructor(iniciais: T[] = []) {
    this.itens = [...iniciais];
  }

  entrar(item: T): void {
    this.itens.push(item);
  }

  sair(): T | undefined {
    return this.itens.shift();
  }

  espreitar(): T | undefined {
    return this.itens[0];
  }

  tamanho(): number {
    return this.itens.length;
  }

  mapear<U>(transformar: (item: T) => U): Fila<U> {
    return new Fila(this.itens.map(transformar));
  }
}

const nomes = new Fila(["Ana", "Bruno", "Carla"]); // Fila<string>
nomes.entrar("Duarte");

console.log(nomes.espreitar()); // "Ana"
console.log(nomes.sair()); // "Ana"
console.log(nomes.tamanho()); // 3

const comprimentos = nomes.mapear((nome) => nome.length); // Fila<number>
console.log(comprimentos.itens.join(",")); // "5,5,6"

// @ts-expect-error a fila é de string: um number não entra
nomes.entrar(1);

type Resultado<T> =
  | { ok: true; valor: T }
  | { ok: false; erro: string };

class Tentativa<T> {
  resultado: Resultado<T>;

  constructor(resultado: Resultado<T>) {
    this.resultado = resultado;
  }

  static sucesso<U>(valor: U): Tentativa<U> {
    return new Tentativa<U>({ ok: true, valor });
  }

  static falha<U>(erro: string): Tentativa<U> {
    return new Tentativa<U>({ ok: false, erro });
  }

  // @ts-expect-error um estático não pode usar o T da classe: tem de declarar o seu próprio
  static vazia(): Tentativa<T> {
    return Tentativa.falha("sem valor");
  }

  mapear<U>(transformar: (valor: T) => U): Tentativa<U> {
    return this.resultado.ok
      ? Tentativa.sucesso(transformar(this.resultado.valor))
      : Tentativa.falha<U>(this.resultado.erro);
  }

  valorOu(alternativa: T): T {
    return this.resultado.ok ? this.resultado.valor : alternativa;
  }
}

const numero = Tentativa.sucesso(21); // Tentativa<number>
console.log(numero.mapear((n) => n * 2).valorOu(0)); // 42

const falhado = Tentativa.falha<number>("sem ligação");
console.log(falhado.mapear((n) => n * 2).valorOu(-1)); // -1

console.log(Tentativa.sucesso("api").mapear((s) => s.length).valorOu(0)); // 3
